from pathlib import Path
import json,re,hashlib,platform,subprocess
base=Path('docs/evidence/i4c')
def read(path):
 b=Path(path).read_bytes()
 return b.decode('utf-16') if b.startswith((b'\xff\xfe',b'\xfe\xff')) else b.decode('utf-8-sig')
def summary(name):
 s=read(base/name)
 return {k:int(v) for k,v in re.findall(r'^# (tests|pass|fail|skipped|cancelled) (\d+)',s,re.M)}
style=read(base/'style-conformance.log')
failures=[f.strip() for f in re.findall(r'^not ok \d+ - (.+)$',style,re.M)]
inv=json.loads((base/'layer-inventory.json').read_text())
tokens={'Elevation':['#352A68','#286B9E','#4A9C9A','#B89B55','#F3E8C8'],'Slope':['#357F78','#DCCB67','#DF8B45','#A83232'],'Thermal':['#1E0C45','#61136E','#BC3754','#F98B0B','#F4E156']}
records=[]
for r in inv['records']:
 if r['category'] not in ['Elevation','Hillshade','Slope','Thermal']:continue
 records.append({'region':r['region'],'id':r['id'],'expectedNameStem':r['standardName'],'actualName':r['display_name'],'expectedEvidence':'Derived' if r['category'] in ['Elevation','Slope','Hillshade'] else 'Observed with processing disclosure','actualEvidence':r['evidence'],'expectedColors':tokens.get(r['category'],'neutral grayscale with source-specific intensity metadata'),'actualColors':[i['color'] for i in r['legend']['items']],'expectedResolutionField':'Explicit immediately associated Resolution field, unavailable when unknown','actualResolutionMetadata':r['spatial_resolution_m'],'source':r['source_id'],'evidenceReference':'layer-inventory.json#'+r['id'],'failures':[f for f in failures if f.startswith('I4C '+r['id']+':')]})
(base/'layer-style-conformance.json').write_text(json.dumps({'stage':'A','sourceRevision':inv['sourceRevision'],'specification':'docs/SCIENTIFIC_LAYER_STYLE_GUIDE.md','specificationStatus':'proposed; not applied','summary':summary('style-conformance.log'),'records':records,'unresolvedIssues':['I4C-01','I4C-02','I4C-03','I4C-04','I4C-05','I4C-06','I4C-07','I4C-08'],'log':'style-conformance.log'},indent=2)+'\n')
commands=json.loads(read(base/'command-results.json'))
result={'stage':'A','sourceRevision':inv['sourceRevision'],'timezone':'Asia/Rangoon','date':'2026-11-15','environment':{'platform':platform.platform(),'python':platform.python_version(),'node':subprocess.check_output(['node','--version'],text=True).strip(),'next':'16.4.6','dependencies':'private npm ci --offline from unchanged lockfile','browser':'Chromium, software WebGL; production localhost port 3346'},'commands':commands,'unitBaseline':summary('baseline-unit.log'),'allUnitIncludingI4C':summary('all-unit.log'),'newNumerical':summary('i4c-numerical.log'),'scientificIntegrity':summary('scientific-integrity.log'),'styleConformance':summary('style-conformance.log'),'python':{'run':190,'passed':186,'skipped':4,'skipReason':'optional raw DEM/weather/PDS caches; not runtime workers'},'assets':{'identical':7282,'gale':2163,'jezero':4124,'oxia':995},'routing':{'independentReplay':'numerical.log','freshReceipts':'generated by baseline full unit run before numerical replay','separateMetrics':['native graph objective','Mars horizontal arc','DEM 3D distance','ascent/descent','bounded snap displacement'],'registrationVerified':False,'jezeroComputationalMaximumDegrees':25,'oxiaTerrainAvailable':False,'fullNativeJezeroReaggregation':'not repeated'},'sourceReview':'primary-source-review.json','limitations':['conditional constant-rate EVA; no operational approval','no full independent native-sensor recalibration','live Three Forks and mineral service fetch unavailable; stored source captures reviewed','NASA lunar 20 degree planning context is not a Mars safety requirement','perceptual/color-vision palette validation pending implementation'],'stageB':{'status':'pending','finalI4DSha':None,'reason':'Exact completed I4D commit not delivered; no final acceptance report or final-acceptance.json created'}}
(base/'independent-validation.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:result[k] for k in ['unitBaseline','allUnitIncludingI4C','scientificIntegrity','styleConformance']},indent=2))
